<style scoped lang="scss" src="./icon-button.scss"></style>

<script>
import { Component, Prop, Vue } from "vue-property-decorator";
import { has } from "../../util/has";
import Icon from "../icon/icon";
import { IconShapeValues } from "../icon/icon.constants";

/**
 * A round button with a simple icon in the middle.
 */
@Component({
  components: { Icon },
})
export default class IconButton extends Vue {
  @Prop({ type: Number, validator: has(IconShapeValues) }) shape;
}
</script>

<template>
  <div class="IconButton" @click="$emit('click')">
    <Icon :shape="shape" :size="24" />
  </div>
</template>
